"""Portfolio tester: 4 sub-programs (runs/evolve_overnight/candidates/cand1_gen037_0.6994.py, evolve/proposals/macrosweep.py, evolve/proposals/wallbreaker.py, evolve/proposals/resonator.py). Worker i runs sub-program i % n; archive slots are partitioned per sub-program."""
import jax, jax.numpy as jnp

# EVOLVE-BLOCK-START
_SRC = ['"""Tester program (evolvable). The four hooks below define how a batch of B workers explores a Kinetix level.\nKinetix states are save/restore-able: the harness keeps K archive slots; `restore` may jump a worker to a stored\nstate, `archive` may store the worker\'s current state. Everything must be pure JAX (jit/vmap-compatible, fixed shapes).\n\nFeature vector `feats` (per worker, F floats, oracle-blind):\n  [0:2] dyn_pos (centroid of moving shapes), [2:4] dyn_vel, [4] dyn_max_speed, [5:7] green_pos, [7] green_blue_dist,\n  [8] time_frac, [9:11] blue_pos, then per-polygon pos/vel/rot/active/role blocks, per-circle pos/vel/active/role blocks,\n  then contact flags. `obs` is Kinetix\'s symbolic observation. Actions: 0..2*NM-1 motor +/- (NM=4 motor bindings),\n  2*NM = no-op, 2*NM+1.. thrusters (2 bindings).\nGoal of the search: reach states that expose planted defects as fast as possible (steps-to-first-witness), and do so\nin a way that generalizes to defect classes the search never saw."""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nBITS = 12            # hash bits for coverage-pool archive cells\nP_RESTORE = 0.06      # per-step probability that a worker jumps to an archived state\nMAX_SHORT = 5         # max repeat length for short random-exploration holds\nMAX_MED = 14          # max repeat length for medium thruster-biased holds\nMAX_LONG = 42         # max repeat length for long single-direction / thruster holds (energy pumping)\nMAX_PUMP = 60          # max repeat length for resonant motor-oscillation holds (swing-pump energy buildup)\nCELL_DIMS = (0, 1, 2, 3, 5, 6, 9, 10)   # feature dims used to define coverage cells\nCELL_RES = 0.5        # coarse grid resolution for coverage cells\nPOOL_FRAC = (0.55, 0.25, 0.20)   # coverage / speed / proximity pool fractions of K\nEXTREME_BONUS = 0.38  # restore-logit bonus for speed/proximity pool slots\nNM = 4                # motor bindings (fixed by env spec)\ndef _split(K):\n    K1 = max(1, int(round(POOL_FRAC[0] * K)))\n    K2 = max(1, int(round(POOL_FRAC[1] * K)))\n    K1 = max(1, K - K2 - max(1, K - K1 - K2))\n    K3 = max(1, K - K1 - K2)\n    K1 = K - K2 - K3\n    return K1, K2, K3\ndef init(rng, F, n_act, K, B):\n    K1, K2, K3 = _split(K)\n    return {"n_act": jnp.int32(n_act), "K": jnp.int32(K), "cur": jnp.zeros(B, jnp.int32),\n            "left": jnp.zeros(B, jnp.int32), "mode": jnp.zeros(B, jnp.int32),\n            "osc_motor": jnp.zeros(B, jnp.int32), "osc_period": jnp.ones(B, jnp.int32),\n            "proj": jax.random.normal(rng, (len(CELL_DIMS), BITS)),\n            "cell_slot": jnp.full(2 ** BITS, -1, jnp.int32), "next_free": jnp.int32(0)}\ndef _cell(mem, feats):\n    x = jnp.round(feats[:, jnp.array(CELL_DIMS)] / CELL_RES) * CELL_RES\n    return ((x @ mem["proj"] > 0) * (2 ** jnp.arange(BITS))).sum(-1).astype(jnp.int32)\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    K1, K2, K3 = _split(K)\n    k1, k2 = jax.random.split(rng)\n    do = jax.random.uniform(k1, (B,)) < P_RESTORE\n    idx = jnp.arange(K)\n    bonus = jnp.where(idx >= K1, EXTREME_BONUS, 0.0)\n    logits = jnp.where(arch_valid, -0.5 * jnp.log1p(arch_visits.astype(jnp.float32)) + bonus, -jnp.inf)\n    slot = jnp.argmax(logits[None, :] + jax.random.gumbel(k2, (B, K)), axis=1)\n    return do & arch_valid.any(), slot, mem\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; n_act = mem["n_act"]\n    k1, k2, k3, k4, k5, k6, k7 = jax.random.split(rng, 7)\n    new = mem["left"] <= 0\n    # 0: short random exploration, 1: long single-motor energy pump, 2: medium thruster hold,\n    # 3: long thruster burst, 4: resonant motor oscillation (swing-pump for extra kinetic energy)\n    mode_probs = jnp.array([0.20, 0.20, 0.20, 0.20, 0.20])\n    mode_probs = jnp.array([0.15, 0.22, 0.15, 0.20, 0.28])   # favor energy-building modes (1,3,4) for TUNNEL\n    mode = jnp.where(new, jax.random.choice(k1, 5, (B,), p=mode_probs), mem["mode"])\n    rand_action = jax.random.randint(k2, (B,), 0, n_act)\n    thr_lo = 2 * NM + 1\n    thr_span = jnp.maximum(n_act - thr_lo, 1)\n    thr_action = thr_lo + jax.random.randint(k3, (B,), 0, thr_span)\n    thr_action = jnp.where(n_act > thr_lo, thr_action, rand_action)\n    is_thruster_mode = (mode == 2) | (mode == 3)\n    new_action = jnp.where(is_thruster_mode, thr_action, rand_action)\n    short_len = jax.random.randint(k4, (B,), 1, MAX_SHORT + 1)\n    med_len = jax.random.randint(k4, (B,), 6, MAX_MED + 1)\n    long_len = jax.random.randint(k5, (B,), 15, MAX_LONG + 1)\n    pump_len = jax.random.randint(k5, (B,), 30, MAX_PUMP + 1)\n    rep_len = jnp.where(mode == 4, pump_len,\n                         jnp.where((mode == 1) | (mode == 3), long_len, jnp.where(mode == 2, med_len, short_len)))\n    osc_motor = jnp.where(new & (mode == 4), jax.random.randint(k6, (B,), 0, NM), mem["osc_motor"])\n    osc_period = jnp.where(new & (mode == 4), jax.random.randint(k7, (B,), 2, 17), mem["osc_period"])\n    left = jnp.where(new, rep_len, mem["left"]) - 1\n    osc_sign = jnp.mod(left // jnp.maximum(osc_period, 1), 2)\n    pump_action = 2 * osc_motor + osc_sign\n    cur = jnp.where(new, new_action, mem["cur"])\n    cur = jnp.where(mode == 4, pump_action, cur)\n    return cur, {**mem, "cur": cur, "left": left, "mode": mode, "osc_motor": osc_motor, "osc_period": osc_period}\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    K = arch_valid.shape[0]\n    K1, K2, K3 = _split(K)\n    live = ~done\n    # coverage pool: hash-grid novelty over first K1 slots\n    cell = _cell(mem, feats)\n    is_new_cell = (mem["cell_slot"][cell] < 0) & live\n    order = jnp.cumsum(is_new_cell) - 1\n    cov_slot = (mem["next_free"] + order) % K1\n    # speed pool: keep the K2 highest dyn_max_speed states seen\n    sub_speed = arch_feats[K1:K1 + K2, 4]\n    sub_speed_valid = arch_valid[K1:K1 + K2]\n    masked_speed = jnp.where(sub_speed_valid, sub_speed, -jnp.inf)\n    worst_speed_idx = jnp.argmin(masked_speed)\n    worst_speed_val = masked_speed[worst_speed_idx]\n    speed_beats = (feats[:, 4] > worst_speed_val) & live\n    speed_slot = K1 + worst_speed_idx\n    # proximity pool: keep the K3 states with smallest green_blue_dist\n    sub_dist = arch_feats[K1 + K2:K, 7]\n    sub_dist_valid = arch_valid[K1 + K2:K]\n    masked_dist = jnp.where(sub_dist_valid, sub_dist, jnp.inf)\n    worst_dist_idx = jnp.argmax(masked_dist)\n    worst_dist_val = masked_dist[worst_dist_idx]\n    dist_beats = (feats[:, 7] < worst_dist_val) & live\n    dist_slot = K1 + K2 + worst_dist_idx\n    use_speed = speed_beats & ~is_new_cell\n    use_dist = dist_beats & ~is_new_cell & ~use_speed\n    do = is_new_cell | use_speed | use_dist\n    slot = jnp.where(is_new_cell, cov_slot, jnp.where(use_speed, speed_slot, dist_slot))\n    cell_slot = mem["cell_slot"].at[jnp.where(is_new_cell, cell, 0)].set(\n        jnp.where(is_new_cell, cov_slot, mem["cell_slot"][0]))\n    return do, slot, {**mem, "cell_slot": cell_slot, "next_free": (mem["next_free"] + is_new_cell.sum()) % K1}\n# EVOLVE-BLOCK-END\n\n\n', '"""Checkpointed action-macro sweep ("macrosweep") -- a breadth-first tree search over structured action programs.\n\nIdea: sticky-random actions almost never produce the *coherent* input programs a human tester tries first: hold one\nmotor to the stop for a second, reverse it rhythmically, fire a thruster continuously, pulse it, sweep every motor in\nturn. This program enumerates such macros deterministically instead of sampling them.\n(1) act() replays a fixed library of ~36 macros (sustained holds, fast/slow reversals, thruster holds and pulse\n    trains, thruster+motor interleaves, all-motor sweeps, a settle macro, and short-burst variants for finer\n    branching); each worker advances to the next macro in the library every time one finishes, so the batch sweeps\n    the whole library rather than re-sampling the same few behaviours.\n(2) The archive is the search *frontier*: a macro endpoint is stored only if it is farther than NOV_EPS from every\n    stored state in a scaled position/velocity metric, plus any mid-macro state that gets unusually fast.\n(3) restore() fires exactly when a macro finishes and sends each worker to a *different* least-expanded frontier node\n    (ranked by the harness\'s visit counts, with noise for ties). The result is a breadth-first expansion of the\n    (state x macro) product: depth comes from chaining macros through checkpoints, breadth from the library.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nMACRO_L = 20        # length of a full macro\nSHORT_L = 6         # length of the short-burst macros (finer branching factor)\nNOV_EPS = 0.30      # novelty radius (scaled feature units) required to store an endpoint\nNOV_DIMS = (0, 1, 2, 3, 4, 5, 6, 9, 10)                    # dyn pos/vel/speed, green pos, blue pos\nNOV_SCALE = (1.0, 1.0, 0.25, 0.25, 0.25, 1.0, 1.0, 1.0, 1.0)\nEPS_RAND = 0.03     # tiny action noise, breaks symmetry between workers on identical checkpoints\nSPD_HOT = 4.0       # mid-macro store threshold on dyn_max_speed\nVIS_NOISE = 0.9     # tie-break noise on the frontier visit ranking\n\n\ndef _macros(n_act):\n    """Deterministic macro library: (M, MACRO_L) action table + per-macro length."""\n    nm = max(1, (n_act - 3) // 2); noop = 2 * nm\n    thr = [noop + 1 + t for t in range(max(0, n_act - 1 - 2 * nm))] or [noop]\n    ms = []\n    def add(pat, L): ms.append(([int(pat[i % len(pat)]) for i in range(MACRO_L)], L))\n    for m in range(nm):\n        add([2 * m], MACRO_L); add([2 * m + 1], MACRO_L)                    # sustained pushes\n        add([2 * m, 2 * m, 2 * m + 1, 2 * m + 1], MACRO_L)                  # fast reversal\n        add([2 * m] * 5 + [2 * m + 1] * 5, MACRO_L)                         # slow reversal\n    for t in thr:\n        add([t], MACRO_L); add([t, t, noop, noop], MACRO_L)                 # thruster hold / pulse train\n    for m in range(nm):\n        add([thr[m % len(thr)], 2 * m], MACRO_L)                            # thrust + motor interleave\n    add([2 * m for m in range(nm)], MACRO_L); add([2 * m + 1 for m in range(nm)], MACRO_L)\n    add([noop], MACRO_L)                                                    # settle\n    for m in range(nm):\n        add([2 * m], SHORT_L); add([2 * m + 1], SHORT_L)                    # short bursts\n    add([thr[0], noop], SHORT_L)\n    return [p for p, _ in ms], [L for _, L in ms]\n\n\ndef init(rng, F, n_act, K, B):\n    tab, ln = _macros(n_act)\n    M = len(tab)\n    return {"n_act": jnp.int32(n_act), "K": jnp.int32(K), "M": jnp.int32(M),\n            "table": jnp.array(tab, jnp.int32), "mlen": jnp.array(ln, jnp.int32),\n            "nov": jnp.array(NOV_DIMS, jnp.int32), "sc": jnp.array(NOV_SCALE, jnp.float32),\n            "mid": jnp.arange(B, dtype=jnp.int32) % jnp.int32(M), "ph": jnp.zeros(B, jnp.int32),\n            "at_end": jnp.zeros(B, bool), "next_free": jnp.int32(0)}\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    key = jnp.where(arch_valid, arch_visits.astype(jnp.float32) + VIS_NOISE * jax.random.uniform(rng, (K,)), 1e6)\n    slot = jnp.argsort(key)[jnp.arange(B) % K]           # distinct least-expanded frontier nodes\n    return mem["at_end"] & arch_valid.any(), slot, mem\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; k1, k2 = jax.random.split(rng)\n    ph = jnp.clip(mem["ph"], 0, mem["table"].shape[1] - 1)\n    a = mem["table"][mem["mid"], ph]\n    a = jnp.where(jax.random.uniform(k1, (B,)) < EPS_RAND, jax.random.randint(k2, (B,), 0, mem["n_act"]), a)\n    nxt = mem["ph"] + 1\n    end = nxt >= mem["mlen"][mem["mid"]]\n    return a.astype(jnp.int32), {**mem, "ph": jnp.where(end, 0, nxt),\n                                 "mid": jnp.where(end, (mem["mid"] + 1) % mem["M"], mem["mid"]), "at_end": end}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    x = feats[:, mem["nov"]] * mem["sc"]\n    y = arch_feats[:, mem["nov"]] * mem["sc"]\n    d2 = ((x[:, None, :] - y[None, :, :]) ** 2).sum(-1)\n    mind = jnp.min(jnp.where(arch_valid[None, :], d2, 1e12), axis=1)\n    store = (~done) & (mem["at_end"] | (feats[:, 4] > SPD_HOT)) & (mind > NOV_EPS ** 2)\n    slot = (mem["next_free"] + jnp.cumsum(store) - 1) % mem["K"]\n    return store, slot, {**mem, "next_free": (mem["next_free"] + store.sum()) % mem["K"]}\n# EVOLVE-BLOCK-END\n\n\n', '"""Boundary-seeking escape search ("wallbreaker").\n\nIdea: most planted defects that matter live at the *edges* of the reachable set, so this program optimises a single\nscalar -- how far the outermost movable shape is from the arena centre, plus how fast it is still moving outward.\n(1) A self-calibrating mobility mask learns online which shape indices ever move, so static walls (which sit outside\n    the box and would dominate any extremeness statistic) are excluded automatically without any oracle knowledge.\n(2) act() is a per-worker (1+1) hill-climber on the action *distribution*: each worker holds a preference logit vector,\n    perturbs it every HOLD steps, and keeps the perturbation only if the batch of steps made progress along the\n    worker\'s assigned compass direction; stalled workers pick a new direction. This finds sustained directional pushes\n    that sticky-random actions almost never produce.\n(3) The archive is an elite pool over the boundary score: each step the weakest slots are offered to the workers and\n    overwritten only by strictly better states, so restores branch from the current record-holders (plus a small\n    random-slot channel for diversity). Escaping the box (OOB), ramming a wall hard enough to pass through a\n    non-solid obstacle (TUNNEL) and extreme sustained pushes (ANOMALY) all fall out of the same objective.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nCENTER = 2.5        # centre of the 5x5 arena; scores are measured relative to it\nBETA_VEL = 0.5      # weight of the outward radial velocity in the boundary score\nMOB_THR = 0.03      # speed above which a shape index is considered movable (learned online)\nP_BASE = 0.02       # baseline per-step restore probability\nP_STALL = 0.30      # restore probability once a worker has stalled\nSTALL_T = 20        # steps without a new outward record before a worker counts as stalled\nREDIR_T = 60        # steps stalled before a worker draws a new escape direction\nTEMP = 1.5          # inverse temperature on archive boundary scores\nHOLD = 8            # length of one hill-climbing trial block\nSIGMA = 1.5         # perturbation scale of the action-preference logits\nSTICKY = 0.55       # probability of repeating the previous action inside a block\nEPS_RAND = 0.10     # uniform-random action rate\nMARGIN = 0.01       # improvement required to evict an elite slot\nP_DIVERSE = 0.07    # probability of storing into a random slot regardless of score\nDIRS = ((1.0, 0.0), (0.7071, 0.7071), (0.0, 1.0), (-0.7071, 0.7071),\n        (-1.0, 0.0), (-0.7071, -0.7071), (0.0, -1.0), (0.7071, -0.7071))\n\n\ndef _idx(F):\n    """Recover the per-shape feature blocks from the feature width (unique for every Kinetix size)."""\n    sols = [(p, c) for p in range(4, 41) for c in range(0, 41)\n            if 11 + 7 * p + 6 * c + (p * (p - 1) // 2 - 6) + c * p + c * (c - 1) // 2 == F]\n    if len(sols) != 1:\n        return dict(use=0.0, px=[0], py=[1], vx=[2], vy=[3], ai=[8])\n    Np, Nc = sols[0]\n    P = 11; PV = P + 2 * Np; PA = PV + 2 * Np + Np; C = PA + 2 * Np; CV = C + 2 * Nc; CA = CV + 2 * Nc\n    return dict(use=1.0,\n                px=[P + 2 * i for i in range(Np)] + [C + 2 * i for i in range(Nc)],\n                py=[P + 2 * i + 1 for i in range(Np)] + [C + 2 * i + 1 for i in range(Nc)],\n                vx=[PV + 2 * i for i in range(Np)] + [CV + 2 * i for i in range(Nc)],\n                vy=[PV + 2 * i + 1 for i in range(Np)] + [CV + 2 * i + 1 for i in range(Nc)],\n                ai=[PA + i for i in range(Np)] + [CA + i for i in range(Nc)])\n\n\ndef _w(mem, X):\n    """Weights of shapes that are active AND have been seen to move (walls therefore get weight 0)."""\n    return X[:, mem["ai"]] * (mem["mob"] > MOB_THR).astype(jnp.float32) * mem["use"]\n\n\ndef _out_score(mem, X):\n    """How close to / far past the box boundary the outermost movable shape is (+ outward momentum). X: (N, F)."""\n    dx = X[:, mem["px"]] - CENTER; dy = X[:, mem["py"]] - CENTER\n    vx = X[:, mem["vx"]]; vy = X[:, mem["vy"]]\n    rad = (dx * vx + dy * vy) / (jnp.sqrt(dx * dx + dy * dy) + 1e-3)\n    s = jnp.maximum(jnp.abs(dx), jnp.abs(dy)) + BETA_VEL * jnp.tanh(0.3 * rad)\n    s_shape = jnp.max(jnp.where(_w(mem, X) > 0.5, s, -1e6), axis=-1)\n    cx = X[:, 0] - CENTER; cy = X[:, 1] - CENTER\n    crad = (cx * X[:, 2] + cy * X[:, 3]) / (jnp.sqrt(cx * cx + cy * cy) + 1e-3)\n    s_cent = jnp.maximum(jnp.abs(cx), jnp.abs(cy)) + BETA_VEL * jnp.tanh(0.3 * crad)\n    return jnp.maximum(s_shape, s_cent)\n\n\ndef _progress(mem, X, d):\n    """Signed extent of the movable shapes along each row\'s escape direction d: (N, 2)."""\n    px = X[:, mem["px"]] - CENTER; py = X[:, mem["py"]] - CENTER\n    proj = px * d[:, 0:1] + py * d[:, 1:2]\n    p_shape = jnp.max(jnp.where(_w(mem, X) > 0.5, proj, -1e6), axis=-1)\n    return jnp.maximum(p_shape, (X[:, 0] - CENTER) * d[:, 0] + (X[:, 1] - CENTER) * d[:, 1])\n\n\ndef init(rng, F, n_act, K, B):\n    ix = _idx(F); k1, k2 = jax.random.split(rng)\n    dirs = jnp.array(DIRS, jnp.float32)\n    return {"n_act": jnp.int32(n_act),\n            "px": jnp.array(ix["px"], jnp.int32), "py": jnp.array(ix["py"], jnp.int32),\n            "vx": jnp.array(ix["vx"], jnp.int32), "vy": jnp.array(ix["vy"], jnp.int32),\n            "ai": jnp.array(ix["ai"], jnp.int32), "use": jnp.float32(ix["use"]),\n            "mob": jnp.zeros(len(ix["px"]), jnp.float32),\n            "dirs": dirs, "dir": dirs[jax.random.randint(k1, (B,), 0, len(DIRS))],\n            "base": jnp.zeros((B, n_act), jnp.float32),\n            "trial": SIGMA * jax.random.normal(k2, (B, n_act), jnp.float32),\n            "best": jnp.full((B,), -1e6, jnp.float32), "p0": jnp.zeros(B, jnp.float32),\n            "pmax": jnp.full((B,), -1e6, jnp.float32), "stall": jnp.zeros(B, jnp.int32),\n            "left": jnp.zeros(B, jnp.int32), "cur": jnp.zeros(B, jnp.int32),\n            "sscore": jnp.full(K + 1, -1e6, jnp.float32)}\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; k1, k2 = jax.random.split(rng)\n    s = _out_score(mem, arch_feats) - 0.15 * jnp.log1p(arch_visits.astype(jnp.float32))\n    logits = jnp.where(arch_valid, TEMP * s, -1e9)\n    slot = jnp.argmax(logits[None, :] + jax.random.gumbel(k2, (B, K), jnp.float32), axis=1)\n    p = jnp.where(mem["stall"] > STALL_T, P_STALL, P_BASE)\n    do = (jax.random.uniform(k1, (B,)) < p) & arch_valid.any()\n    return do, slot, {**mem, "stall": jnp.where(do, 0, mem["stall"]),\n                      "pmax": jnp.where(do, jnp.float32(-1e6), mem["pmax"])}\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; k1, k2, k3, k4, k5, k6 = jax.random.split(rng, 6)\n    prog = _progress(mem, feats, mem["dir"])\n    newb = mem["left"] <= 0\n    better = (prog - mem["p0"]) > mem["best"]\n    base = jnp.where((newb & better)[:, None], mem["trial"], mem["base"])\n    upd = jnp.maximum(jnp.where(better, prog - mem["p0"], mem["best"] * 0.9), 0.0)\n    best = jnp.where(newb, upd, mem["best"])\n    trial = jnp.where(newb[:, None], base + SIGMA * jax.random.normal(k1, base.shape, jnp.float32), mem["trial"])\n    a = jax.random.categorical(k2, trial)\n    a = jnp.where(jax.random.uniform(k3, (B,)) < EPS_RAND, jax.random.randint(k4, (B,), 0, mem["n_act"]), a)\n    a = jnp.where((jax.random.uniform(k5, (B,)) < STICKY) & ~newb, mem["cur"], a).astype(jnp.int32)\n    stall = jnp.where(prog > mem["pmax"] + 1e-3, 0, mem["stall"] + 1)\n    pmax = jnp.maximum(mem["pmax"], prog)\n    redir = stall > REDIR_T\n    d = jnp.where(redir[:, None], mem["dirs"][jax.random.randint(k6, (B,), 0, len(DIRS))], mem["dir"])\n    return a, {**mem, "base": base, "trial": trial, "best": best, "cur": a,\n               "p0": jnp.where(newb, prog, mem["p0"]), "left": jnp.where(newb, HOLD, mem["left"]) - 1,\n               "pmax": jnp.where(redir, prog, pmax), "stall": jnp.where(redir, 0, stall), "dir": d}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; k1, k2 = jax.random.split(rng)\n    spd = jnp.sqrt(feats[:, mem["vx"]] ** 2 + feats[:, mem["vy"]] ** 2) * feats[:, mem["ai"]]\n    mob = jnp.maximum(mem["mob"], spd.max(0) * mem["use"])\n    sc = _out_score({**mem, "mob": mob}, feats)\n    eff = jnp.where(arch_valid, mem["sscore"][:K], jnp.float32(-1e6))\n    tgt = jnp.argsort(eff)[jnp.arange(B) % K]\n    div = jax.random.uniform(k1, (B,)) < P_DIVERSE\n    slot = jnp.where(div, jax.random.randint(k2, (B,), 0, K), tgt)\n    store = (~done) & (div | (sc > eff[tgt] + MARGIN))\n    sscore = mem["sscore"].at[jnp.where(store, slot, K)].set(jnp.where(store, sc, mem["sscore"][K]))\n    return store, slot, {**mem, "mob": mob, "sscore": sscore}\n# EVOLVE-BLOCK-END\n\n\n', '"""Energy-pumping resonance search ("resonator").\n\nIdea: physics bugs (runaway integration, tunnelling through thin/soft geometry, shapes launched out of the arena) all\nrequire *energy*, and energy is injected by driving actuators in phase with the level\'s own oscillation, not by\nrandom button mashing.\n(1) act() runs five structured drives instead of random actions: motor square waves at a per-worker period, thruster\n    holds, thruster pulse trains, a velocity-feedback pump (push the motor in whichever direction the dynamic\n    centroid is already moving -- the classic playground-swing resonance), and a thruster/motor interleave. Each\n    worker re-rolls its drive after a restore, after an epoch, or when its energy plateaus.\n(2) The archive is an energy *ladder*: slots are partitioned into NB bands by log speed and each band keeps a rotating\n    set of states, so the archive can never collapse onto one state and always retains a staircase of increasingly\n    energetic configurations.\n(3) restore() is an explicit hill-climb: workers jump to the highest occupied band (or a random band for diversity)\n    whenever their own energy record has not improved for PATIENCE steps, so every restore restarts pumping from the\n    fastest state found so far. Repeated pump-and-checkpoint cycles multiply speed geometrically.\n"""\nimport jax, jax.numpy as jnp\n\n# EVOLVE-BLOCK-START\nNB = 8            # number of log-speed bands in the ladder archive\nBPO = 1.6         # bands per octave of log2(1 + energy)\nP_LADDER = 0.05   # baseline per-step restore probability\nPATIENCE = 30     # steps without a personal energy record before forcing a restore\nTOP_FRAC = 0.55   # probability of restoring from the highest occupied band (else a random band)\nP_STORE = 0.10    # probability of storing a non-record state (keeps bands fresh)\nEPOCH = 48        # steps before a worker re-rolls its drive pattern\nPERIODS = (2, 3, 4, 6, 8, 12)\nN_MODE = 5        # square wave / thruster hold / thruster pulse / velocity-feedback pump / interleave\nVEL_W = 0.4       # weight of the centroid speed in the energy score (on top of dyn_max_speed)\n\n\ndef _energy(X):\n    """Kinetic-energy proxy: peak movable-shape speed plus centroid speed. X: (N, F)."""\n    return X[:, 4] + VEL_W * jnp.sqrt(X[:, 2] ** 2 + X[:, 3] ** 2)\n\n\ndef _roll(mem, key, B):\n    """Draw a fresh drive pattern (mode, motor, thruster, period, feedback axis, direction bit) per worker."""\n    k1, k2, k3, k4, k5, k6 = jax.random.split(key, 6)\n    u = jax.random.normal(k5, (B, 2), jnp.float32)\n    return (jax.random.randint(k1, (B,), 0, N_MODE),\n            2 * jax.random.randint(k2, (B,), 0, mem["nm"]),\n            mem["thr"][jax.random.randint(k3, (B,), 0, mem["thr"].shape[0])],\n            mem["per"][jax.random.randint(k4, (B,), 0, mem["per"].shape[0])],\n            u / (jnp.linalg.norm(u, axis=-1, keepdims=True) + 1e-6),\n            jax.random.randint(k6, (B,), 0, 2))\n\n\ndef init(rng, F, n_act, K, B):\n    nm = max(1, (n_act - 3) // 2)               # motor bindings: n_act = 2*NM + 1 (no-op) + NT thrusters\n    noop = 2 * nm\n    thr = [noop + 1 + t for t in range(max(0, n_act - 1 - 2 * nm))] or [noop]\n    S = max(1, K // NB)\n    mem = {"n_act": jnp.int32(n_act), "nm": jnp.int32(nm), "noop": jnp.int32(noop),\n           "thr": jnp.array(thr, jnp.int32), "per": jnp.array(PERIODS, jnp.int32),\n           "S": jnp.int32(S), "K": jnp.int32(K),\n           "ptr": jnp.zeros(NB, jnp.int32), "cnt": jnp.zeros(NB, jnp.int32),\n           "bbest": jnp.full(NB, -1e6, jnp.float32),\n           "ph": jnp.zeros(B, jnp.int32), "pb": jnp.full((B,), -1e6, jnp.float32),\n           "stall": jnp.zeros(B, jnp.int32), "just": jnp.zeros(B, bool)}\n    mode, mot, th, per, u, d = _roll(mem, rng, B)\n    mem.update({"mode": mode, "mot": mot, "tha": th, "prd": per, "u": u, "dbit": d})\n    return mem\n\n\ndef restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]; k1, k2, k3, k4 = jax.random.split(rng, 4)\n    hb = jnp.argmax(jnp.where(mem["cnt"] > 0, jnp.arange(NB), -1))          # highest occupied band\n    band = jnp.where(jax.random.uniform(k1, (B,)) < TOP_FRAC, hb, jax.random.randint(k2, (B,), 0, NB))\n    n = jnp.maximum(jnp.minimum(mem["cnt"][band], mem["S"]), 1)\n    slot = jnp.clip(band * mem["S"] + jax.random.randint(k3, (B,), 0, 1 << 20) % n, 0, K - 1)\n    do = ((jax.random.uniform(k4, (B,)) < P_LADDER) | (mem["stall"] > PATIENCE)) & arch_valid.any()\n    return do, slot, {**mem, "just": do, "stall": jnp.where(do, 0, mem["stall"]),\n                      "pb": jnp.where(do, jnp.float32(-1e6), mem["pb"])}\n\n\ndef act(mem, feats, obs, rng):\n    B = feats.shape[0]; k1, k2, k3 = jax.random.split(rng, 3)\n    E = _energy(feats)\n    rec = E > mem["pb"] + 1e-3\n    stall = jnp.where(rec, 0, mem["stall"] + 1)\n    reroll = mem["just"] | (mem["ph"] >= EPOCH) | (stall > PATIENCE)\n    mode, mot, tha, prd, u, dbit = _roll(mem, k1, B)\n    mode = jnp.where(reroll, mode, mem["mode"]); mot = jnp.where(reroll, mot, mem["mot"])\n    tha = jnp.where(reroll, tha, mem["tha"]); prd = jnp.where(reroll, prd, mem["prd"])\n    u = jnp.where(reroll[:, None], u, mem["u"]); dbit = jnp.where(reroll, dbit, mem["dbit"])\n    ph = jnp.where(reroll, 0, mem["ph"])\n    half = (ph // prd) % 2\n    pump = (feats[:, 2] * u[:, 0] + feats[:, 3] * u[:, 1] < 0).astype(jnp.int32)\n    a = jnp.where(mode == 0, mot + half,\n        jnp.where(mode == 1, tha,\n        jnp.where(mode == 2, jnp.where(half == 0, tha, mem["noop"]),\n        jnp.where(mode == 3, mot + pump,\n                  jnp.where(ph % 2 == 0, tha, mot + dbit)))))\n    a = jnp.where(jax.random.uniform(k2, (B,)) < 0.05, jax.random.randint(k3, (B,), 0, mem["n_act"]), a)\n    return a.astype(jnp.int32), {**mem, "mode": mode, "mot": mot, "tha": tha, "prd": prd, "u": u, "dbit": dbit,\n                                 "ph": ph + 1, "pb": jnp.maximum(mem["pb"], E),\n                                 "stall": jnp.where(reroll, 0, stall), "just": jnp.zeros(B, bool)}\n\n\ndef archive(mem, feats, done, arch_feats, arch_valid, rng):\n    B = feats.shape[0]; K = arch_valid.shape[0]\n    E = _energy(feats)\n    band = jnp.clip((jnp.log2(1.0 + jnp.maximum(E, 0.0)) * BPO).astype(jnp.int32), 0, NB - 1)\n    rank = ((band[:, None] == band[None, :]) & (jnp.arange(B)[:, None] > jnp.arange(B)[None, :])).sum(-1)\n    slot = jnp.clip(band * mem["S"] + (mem["ptr"][band] + rank) % mem["S"], 0, K - 1)\n    store = (~done) & ((mem["cnt"][band] < mem["S"]) | (E > mem["bbest"][band] - 0.02)\n                       | (jax.random.uniform(rng, (B,)) < P_STORE))\n    inc = store.astype(jnp.int32)\n    ptr = mem["ptr"].at[band].add(inc)\n    cnt = jnp.minimum(mem["cnt"].at[band].add(inc), mem["S"])\n    bbest = mem["bbest"].at[band].max(jnp.where(store, E, jnp.float32(-1e6)))\n    return store, slot, {**mem, "ptr": ptr, "cnt": cnt, "bbest": bbest}\n# EVOLVE-BLOCK-END\n\n\n']
_P = []
for _s in _SRC:
    _ns = {"jax": jax, "jnp": jnp}
    exec(_s, _ns)
    _P.append(_ns)
N_SUB = len(_P)


def _sel(outs_b, group):
    """outs_b: list of (B,) arrays, one per sub-program -> per-worker selection by group."""
    st = jnp.stack(outs_b)
    return st[group, jnp.arange(group.shape[0])]


def init(rng, F, n_act, K, B):
    keys = jax.random.split(rng, N_SUB)
    Ki = K // N_SUB
    return {"sub": [_P[i]["init"](keys[i], F, n_act, Ki, B) for i in range(N_SUB)], "group": jnp.arange(B) % N_SUB, "Ki": jnp.int32(Ki)}


def restore(mem, feats, arch_feats, arch_valid, arch_visits, rng):
    keys = jax.random.split(rng, N_SUB); Ki = arch_valid.shape[0] // N_SUB
    dos, slots, subs = [], [], []
    for i in range(N_SUB):
        sl = slice(i * Ki, (i + 1) * Ki)
        d, s, m = _P[i]["restore"](mem["sub"][i], feats, arch_feats[sl], arch_valid[sl], arch_visits[sl], keys[i])
        dos.append(d); slots.append(jnp.clip(s, 0, Ki - 1) + i * Ki); subs.append(m)
    g = mem["group"]
    return _sel(dos, g), _sel(slots, g), {**mem, "sub": subs}


def act(mem, feats, obs, rng):
    keys = jax.random.split(rng, N_SUB); acts, subs = [], []
    for i in range(N_SUB):
        a, m = _P[i]["act"](mem["sub"][i], feats, obs, keys[i]); acts.append(a); subs.append(m)
    return _sel(acts, mem["group"]), {**mem, "sub": subs}


def archive(mem, feats, done, arch_feats, arch_valid, rng):
    keys = jax.random.split(rng, N_SUB); Ki = arch_valid.shape[0] // N_SUB
    dos, slots, subs = [], [], []
    for i in range(N_SUB):
        sl = slice(i * Ki, (i + 1) * Ki)
        d, s, m = _P[i]["archive"](mem["sub"][i], feats, done, arch_feats[sl], arch_valid[sl], keys[i])
        # only this sub-program's own workers may store into its partition
        d = d & (mem["group"] == i)
        dos.append(d); slots.append(jnp.clip(s, 0, Ki - 1) + i * Ki); subs.append(m)
    g = mem["group"]
    return _sel(dos, g), _sel(slots, g), {**mem, "sub": subs}
# EVOLVE-BLOCK-END


def run_experiment(**kwargs):
    """Called by the evaluation harness; returns the search-split fitness. Do not edit."""
    import sys, os
    sys.path.insert(0, os.environ.get("AUTODEV_ROOT", os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
    from autodev.search_eval import evaluate_hooks
    return evaluate_hooks(init, restore, act, archive, **kwargs)
